package com.vandorlabs.gear.core;
/** Literal Source/native six-switch oracle, including signed zero and mounted native-grid decisions. */
public final class GearMountFrameChecks {
 private static int checks;private static void same(double a,double b){checks++;if(Double.doubleToLongBits(a)!=Double.doubleToLongBits(b))throw new AssertionError(a+" != "+b);}
 private static void old(int face,double x,double y,double z,double[] a){switch(face){case 1:a[0]=x;a[1]=-y;a[2]=-z;break;case 5:a[0]=-y;a[1]=x;a[2]=z;break;case 4:a[0]=y;a[1]=-x;a[2]=z;break;case 2:a[0]=x;a[1]=-z;a[2]=y;break;case 3:a[0]=x;a[1]=z;a[2]=-y;break;default:a[0]=x;a[1]=y;a[2]=z;}}
 public static void main(String[] args){double[] a=new double[3];double[] values={-64,-7.25,-1,-0D,0D,.5,1,17.125,64};for(int face=0;face<6;face++)for(double x:values)for(double y:values)for(double z:values){old(face,x,y,z,a);same(a[0],GearMountFrame.x(face,x,y,z));same(a[1],GearMountFrame.y(face,x,y,z));same(a[2],GearMountFrame.z(face,x,y,z));}
  GearFootProjection p=new GearFootProjection();for(int face=0;face<6;face++)for(int size=1;size<=2;size++)for(ArmHinge.Mode hinge:ArmHinge.Mode.values())for(GearMotion.Direction direction:GearMotion.Direction.values())for(GearMotion.Direction kink:GearMotion.Direction.values())for(GearMotion.Mode mode:new GearMotion.Mode[]{GearMotion.Mode.ROTATE,GearMotion.Mode.ROTATE_LEVEL})for(int phase=0;phase<=1;phase++)for(int angle=-180;angle<=180;angle+=15){p.prepare(mode,direction,2,phase,GearMotion.RETRACTED_FOOT_Y,0,size==2?11/16D:9/16D,angle,0,hinge,kink,size);for(int corner=0;corner<8;corner++){p.write(corner&1,-2+((corner>>1)&1),(corner>>2)&1,a,0);double x=GearMountFrame.x(face,a[0]-.5,a[1]-.5,a[2]-.5)+.5,y=GearMountFrame.y(face,a[0]-.5,a[1]-.5,a[2]-.5)+.5,z=GearMountFrame.z(face,a[0]-.5,a[1]-.5,a[2]-.5)+.5;boolean local=Math.abs(a[0]-Math.rint(a[0]))<1e-8&&Math.abs(a[1]-Math.rint(a[1]))<1e-8&&Math.abs(a[2]-Math.rint(a[2]))<1e-8,mounted=Math.abs(x-Math.rint(x))<1e-8&&Math.abs(y-Math.rint(y))<1e-8&&Math.abs(z-Math.rint(z))<1e-8;checks++;if(local!=mounted)throw new AssertionError("Mount changes grid admission");}}
  System.out.println("gear-mount-frame PASS six-mount oracle checks="+checks);
 }
}
